PARAMETERS Forms!InvoicesDialogBox!BeginningDate DateTime, Forms!InvoicesDialogBox!EndingDate DateTime;
SELECT invoice_date, invoice_number, company_name, job_name, sum(amount) AS [Sub Total], ([Sub Total]*0.125) AS GST, ([Sub Total]+[GST]) AS [Invoice Total]
FROM invoices, invoices_detail
WHERE invoice_date Between Forms!InvoicesDialogBox!BeginningDate And Forms!InvoicesDialogBox!EndingDate And invoices.invoice_id=invoices_detail.invoice_id
GROUP BY invoice_date, invoice_number, company_name, job_name;

SELECT Sum([GST_Total]) AS [GST TOTAL]
FROM Transactions
WHERE (((Transactions.Date) Between #4/1/1999# And #9/30/1999#));

PARAMETERS Forms!TransactionsDialogBox!BeginningDate DateTime, Forms!TransactionsDialogBox!EndingDate DateTime, Forms!TransactionsDialogBox!Code1 Text ( 255 ), Forms!TransactionsDialogBox!Code2 Text ( 255 ), Forms!TransactionsDialogBox!Code3 Text ( 255 ), Forms!TransactionsDialogBox!Code4 Text ( 255 ), Forms!TransactionsDialogBox!Code5 Text ( 255 ), Forms!TransactionsDialogBox!Code6 Text ( 255 ), Forms!TransactionsDialogBox!Code7 Text ( 255 ), Forms!TransactionsDialogBox!Code8 Text ( 255 ), Forms!TransactionsDialogBox!Code9 Text ( 255 ), Forms!TransactionsDialogBox!Code10 Text ( 255 );
SELECT transactions.*, description, sub_code_description
FROM Transactions, ledger_accounts
WHERE (((Transactions.transaction_date) Between Forms!TransactionsDialogBox!BeginningDate And Forms!TransactionsDialogBox!EndingDate)) And ((Transactions.Account_Code) Like Forms!TransactionsDialogBox!Code1 Or (Transactions.Account_Code)=Forms!TransactionsDialogBox!Code2 Or (Transactions.Account_Code)=Forms!TransactionsDialogBox!Code3 Or (Transactions.Account_Code)=Forms!TransactionsDialogBox!Code4 Or (Transactions.Account_Code)=Forms!TransactionsDialogBox!Code5 Or (Transactions.Account_Code)=Forms!TransactionsDialogBox!Code6 Or (Transactions.Account_Code)=Forms!TransactionsDialogBox!Code7 Or (Transactions.Account_Code)=Forms!TransactionsDialogBox!Code8 Or (Transactions.Account_Code)=Forms!TransactionsDialogBox!Code9 Or (Transactions.Account_Code)=Forms!TransactionsDialogBox!Code10) And Transactions.Account_Code=ledger_accounts.account_code
ORDER BY transaction_date, transaction_reference;
